/// The names the FreeANDIY themes show in menus and preferences.
pub fn theme_label(kind: ThemeKind) -> Option<&'static str> {
    match kind {
        ThemeKind::StudioLight => Some("FreeANDIY Light"),
        ThemeKind::ProMedium => Some("FreeANDIY Dark"),
        _ => None,
    }
}

/// The FreeANDIY tokens for the two themes that carry them.
pub fn tokens(kind: ThemeKind) -> Option<Tokens> {
    match kind {
        ThemeKind::StudioLight => Some(light()),
        ThemeKind::ProMedium => Some(dark()),
        _ => None,
    }
}

/// Paper and ink: black ideas on an empty page. Flat, square, hairlines instead of shadows; the
/// highlighters mark what is selected, the stamp rose marks what is active.
fn light() -> Tokens {
    let ink = |t: f32| mix(PAPER, BLACK, t);
    Tokens {
        kind: ThemeKind::StudioLight,
        chrome: PAPER,
        canvas: ink(0.10),
        canvas_dot: ink(0.18),
        dock: ink(0.04),
        card: PAPER,
        card_border: ink(0.30),
        field: WHITE,
        field_border: ink(0.30),
        hover: ink(0.07),
        pressed: ink(0.14),
        text: BLACK,
        text_dim: ink(0.70),
        text_faint: ink(0.50),
        icon: BLACK,
        accent: ROSE,
        accent_soft: mix(PAPER, YELLOW, 0.60),
        accent_border: BLACK,
        accent_text: ROSE,
        separator: ink(0.15),
        shadow: Color32::TRANSPARENT,
        primary_bg: BLACK,
        primary_text: PAPER,
        danger: ROSE,
        warning: Color32::from_rgb(176, 120, 0),
        radius_sm: 0.0,
        radius: 0.0,
        radius_lg: 2.0,
        bevel: false,
        pro: false,
        round_chips: false,
        tab_strip: ink(0.04),
        row_selected: mix(PAPER, YELLOW, 0.60),
        histogram_bg: WHITE,
        histogram_level: 90,
        caption_close: ROSE,
        caption_close_text: PAPER,
        scrim: Color32::from_rgba_unmultiplied(35, 31, 32, 110),
    }
}

/// Ink and paper: the same system inverted.
